// Ported from the Node app's Sequelize model TimetableSlot (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class TimetableSlotConfiguration : IEntityTypeConfiguration<TimetableSlot>
{
    public void Configure(EntityTypeBuilder<TimetableSlot> builder)
    {
        builder.ToTable("timetable_slots");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ClassId).HasColumnName("class_id");
        builder.Property(e => e.Day).HasColumnName("day");
        builder.Property(e => e.Period).HasColumnName("period");
        builder.Property(e => e.SubjectId).HasColumnName("subject_id");
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.RoomId).HasColumnName("room_id");
        builder.HasIndex(e => new { e.ClassId, e.Day, e.Period }).IsUnique().HasDatabaseName("uq_slot");
        builder.HasOne(e => e.SchoolClass).WithMany(p => p.TimetableSlots).HasForeignKey(e => e.ClassId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Subject).WithMany(p => p.TimetableSlots).HasForeignKey(e => e.SubjectId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Staff).WithMany(p => p.TimetableSlots).HasForeignKey(e => e.StaffId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Room).WithMany(p => p.TimetableSlots).HasForeignKey(e => e.RoomId).OnDelete(DeleteBehavior.NoAction);
    }
}
